/** ядро_стойност 안의 연결형 байт_стойност поток_стойност. Ethernet/TCP 패킷 스택이 아닌 루프백 socket слой_стойност. */
public final class поток_мрежа {
    static int[] Състояние_стойност = new int[16], порт_стойност = new int[16], 짝 = new int[16], крайно_устройство_порт = new int[16], почакай_стойност = new int[16], информационни_технологии_граница = new int[16];
    static int[] предна_стойност = new int[16], 수 = new int[16], данни = new int[16 * 1024];
    static int Следваща_артикул = 50000;
    static int проверявам(int 열린파일번호) { return 열린파일번호 >= 40 && 열린파일번호 < 56 && Състояние_стойност[열린파일번호 - 40] != 0 ? 열린파일번호 - 40 : -1; }
    static boolean 사용중(int номер_на_порт) { for (int цикъл_индекс = 0; цикъл_индекс < 16; цикъл_индекс++) if (Състояние_стойност[цикъл_индекс] != 0 && информационни_технологии_граница[цикъл_индекс] != 0 && порт_стойност[цикъл_индекс] == номер_на_порт) return true; return false; }
    public static int Създаване_запис() {
        for (int цикъл_индекс = 0; цикъл_индекс < 16; цикъл_индекс++) if (Състояние_стойност[цикъл_индекс] == 0) { Състояние_стойност[цикъл_индекс] = 1; крайно_устройство_порт[цикъл_индекс] = порт_стойност[цикъл_индекс] = предна_стойност[цикъл_индекс] = 수[цикъл_индекс] = почакай_стойност[цикъл_индекс] = информационни_технологии_граница[цикъл_индекс] = 0; 짝[цикъл_индекс] = -1; return цикъл_индекс + 40; }
        return -24;
    }
    public static int обвързвам_участник(int 열린파일번호, int 통신주소, int номер_на_порт) {
        int цикъл_индекс = проверявам(열린파일번호); if (цикъл_индекс < 0) return -9;
        if (통신주소 != 0 && 통신주소 != 0x7f000001) return -99;
        if (Състояние_стойност[цикъл_индекс] != 1 || номер_на_порт < 0 || номер_на_порт > 65535) return -22;
        if (номер_на_порт == 0) { do { номер_на_порт = Следваща_артикул++; if (Следваща_артикул > 65535) Следваща_артикул = 50000; } while (사용중(номер_на_порт)); }
        if (사용중(номер_на_порт)) return -98; порт_стойност[цикъл_индекс] = номер_на_порт; информационни_технологии_граница[цикъл_индекс] = 1; Състояние_стойност[цикъл_индекс] = 2; return 0;
    }
    public static int чакам_участник(int 열린파일번호, int 연결대기한도) { int цикъл_индекс = проверявам(열린파일번호); if (цикъл_индекс < 0) return -9; if (Състояние_стойност[цикъл_индекс] != 2 || 연결대기한도 < 1) return -22; Състояние_стойност[цикъл_индекс] = 3; return 0; }
    public static int Свързване(int 열린파일번호, int 통신주소, int номер_на_порт) {
        int цикъл_индекс = проверявам(열린파일번호); if (цикъл_индекс < 0) return -9; if (통신주소 != 0x7f000001) return -101;
        if (номер_на_порт < 1 || номер_на_порт > 65535 || Състояние_стойност[цикъл_индекс] > 2) return -22;
        int получавам_страница = -1; for (int вътрешно_позиция = 0; вътрешно_позиция < 16; вътрешно_позиция++) if (Състояние_стойност[вътрешно_позиция] == 3 && порт_стойност[вътрешно_позиция] == номер_на_порт) получавам_страница = вътрешно_позиция;
        if (получавам_страница < 0) return -111;
        int 대기여부 = 0; for (int вътрешно_позиция = 0; вътрешно_позиция < 16; вътрешно_позиция++) if (почакай_стойност[вътрешно_позиция] == получавам_страница + 1) 대기여부++;
        if (대기여부 >= 4) return -11;
        if (Състояние_стойност[цикъл_индекс] == 1) { int 처리값 = обвързвам_участник(열린파일번호, 0x7f000001, 0); if (처리값 < 0) return 처리값; }
        int други = Създаване_запис(); if (други < 0) return други; други -= 40;
        Състояние_стойност[цикъл_индекс] = Състояние_стойност[други] = 4; 짝[цикъл_индекс] = други; 짝[други] = цикъл_индекс; порт_стойност[други] = номер_на_порт; крайно_устройство_порт[цикъл_индекс] = номер_на_порт; крайно_устройство_порт[други] = порт_стойност[цикъл_индекс]; почакай_стойност[други] = получавам_страница + 1; return 0;
    }
    public static int приемам_връзка(int 열린파일번호) { int цикъл_индекс = проверявам(열린파일번호); if (цикъл_индекс < 0) return -9; if (Състояние_стойност[цикъл_индекс] != 3) return -22; for (int вътрешно_позиция = 0; вътрешно_позиция < 16; вътрешно_позиция++) if (Състояние_стойност[вътрешно_позиция] != 0 && почакай_стойност[вътрешно_позиция] == цикъл_индекс + 1) { почакай_стойност[вътрешно_позиция] = 0; return вътрешно_позиция + 40; } return -11; }
    public static int Писане(int 열린파일번호, int 항목수) {
        int цикъл_индекс = проверявам(열린파일번호); if (цикъл_индекс < 0) return -9; if (Състояние_стойност[цикъл_индекс] != 4) return -107;
        if (항목수 < 0 || 항목수 > 512) return -22; if (항목수 == 0) return 0;
        int вътрешно_позиция = 짝[цикъл_индекс]; if (вътрешно_позиция < 0) return -32; int 총수 = 1024 - 수[вътрешно_позиция]; if (총수 == 0) return -11; if (총수 > 항목수) 총수 = 항목수;
        for (int Сравнение_позиция = 0; Сравнение_позиция < 총수; Сравнение_позиция++) данни[вътрешно_позиция * 1024 + (предна_стойност[вътрешно_позиция] + 수[вътрешно_позиция] + Сравнение_позиция) % 1024] = обръщане_към_себе_си_за_компютър_в_мрежа_мрежа.Напред_стойност[Сравнение_позиция]; 수[вътрешно_позиция] += 총수; return 총수;
    }
    public static int Четене(int 열린파일번호, int 항목수) {
        int цикъл_индекс = проверявам(열린파일번호); if (цикъл_индекс < 0) return -9; if (Състояние_стойност[цикъл_индекс] != 4) return -107; if (항목수 < 0 || 항목수 > 512) return -22;
        if (항목수 == 0) return 0; if (수[цикъл_индекс] == 0) return 짝[цикъл_индекс] < 0 ? 0 : -11; if (항목수 > 수[цикъл_индекс]) 항목수 = 수[цикъл_индекс];
        for (int Сравнение_позиция = 0; Сравнение_позиция < 항목수; Сравнение_позиция++) обръщане_към_себе_си_за_компютър_в_мрежа_мрежа.Напред_стойност[Сравнение_позиция] = данни[цикъл_индекс * 1024 + (предна_стойност[цикъл_индекс] + Сравнение_позиция) % 1024]; предна_стойност[цикъл_индекс] = (предна_стойност[цикъл_индекс] + 항목수) % 1024; 수[цикъл_индекс] -= 항목수; return 항목수;
    }
    public static int 창구읽기(int 열린파일번호) { int цикъл_индекс = проверявам(열린파일번호); return цикъл_индекс < 0 ? -9 : порт_стойност[цикъл_индекс]; }
    public static int 상대창구읽기(int 열린파일번호) { int цикъл_индекс = проверявам(열린파일번호); return цикъл_индекс < 0 ? -9 : крайно_устройство_порт[цикъл_индекс]; }
    public static int Затворен(int 열린파일번호) {
        int цикъл_индекс = проверявам(열린파일번호); if (цикъл_индекс < 0) return -9;
        if (Състояние_стойност[цикъл_индекс] == 3) for (int вътрешно_позиция = 0; вътрешно_позиция < 16; вътрешно_позиция++) if (почакай_стойност[вътрешно_позиция] == цикъл_индекс + 1) { if (짝[вътрешно_позиция] >= 0) 짝[짝[вътрешно_позиция]] = -1; Състояние_стойност[вътрешно_позиция] = почакай_стойност[вътрешно_позиция] = информационни_технологии_граница[вътрешно_позиция] = 0; }
        if (짝[цикъл_индекс] >= 0) 짝[짝[цикъл_индекс]] = -1; Състояние_стойност[цикъл_индекс] = информационни_технологии_граница[цикъл_индекс] = 수[цикъл_индекс] = почакай_стойност[цикъл_индекс] = 0; return 0;
    }
}
